# More famous Welsh people, part I (12 November 2026): third batch for Ifan's "I want as many historic people as
# possible on the site". Twentieth-century Wales: writers in both languages, painters, composers, singers, actors,
# campaigners, a historian, and the sportsmen who carried the name of Wales round the world.
# Same format and house voice as people2a.py (EDITORIAL.md: proud, nothing negative about Welsh figures).
from people2a import P

PEOPLE = [
 # ---------- Words ----------
 P("caradog-prichard", "modern", "1904–1980", "Caradog Prichard", "Caradog Prichard", "Author of Un Nos Ola Leuad", "Awdur Un Nos Ola Leuad", "Caradog_Prichard", "words",
   "The poet and journalist from Bethesda who won the crown three years running and wrote Un Nos Ola Leuad, often called the greatest novel in Welsh.",
   "Y bardd a’r newyddiadurwr o Fethesda a enillodd y goron dair blynedd yn olynol ac a ysgrifennodd Un Nos Ola Leuad, a elwir yn aml y nofel fwyaf yn y Gymraeg.",
   ["Caradog Prichard was born in 1904 in Bethesda, in the quarrying valley of Dyffryn Ogwen. His father was killed in an accident in the Penrhyn quarry when Caradog was a baby, and he was brought up by his mother through hard years. He became a journalist, first in Caernarfon and then in London, where he worked for many years on the Daily Telegraph.",
    "He won the crown at the National Eisteddfod in 1927, 1928 and 1929, and the chair in 1962. In 1961 he published Un Nos Ola Leuad, One Moonlit Night, in which a boy walks through his village in the dialect of Bethesda and the whole life of the quarrying community rises around him, with its humour, its chapels and its sorrows. It has been translated into many languages, made into a film and a stage play, and is counted among the classics of European writing."],
   ["Ganed Caradog Prichard yn 1904 ym Methesda, yn nyffryn chwareli Dyffryn Ogwen. Lladdwyd ei dad mewn damwain yn chwarel y Penrhyn pan oedd Caradog yn faban, a magwyd ef gan ei fam drwy flynyddoedd caled. Daeth yn newyddiadurwr, yn gyntaf yng Nghaernarfon ac yna yn Llundain, lle gweithiodd am flynyddoedd lawer ar y Daily Telegraph.",
    "Enillodd y goron yn yr Eisteddfod Genedlaethol yn 1927, 1928 a 1929, a’r gadair yn 1962. Yn 1961 cyhoeddodd Un Nos Ola Leuad, lle mae bachgen yn cerdded drwy ei bentref yn nhafodiaith Bethesda ac mae holl fywyd y gymdeithas chwarelyddol yn codi o’i gwmpas, gyda’i hiwmor, ei chapeli a’i gofidiau. Fe’i cyfieithwyd i lawer o ieithoedd, fe’i gwnaed yn ffilm ac yn ddrama lwyfan, ac fe’i cyfrifir ymhlith clasuron llên Ewrop."]),
 P("t-rowland-hughes", "modern", "1903–1949", "T. Rowland Hughes", "T. Rowland Hughes", "Novelist of the quarrymen", "Nofelydd y chwarelwyr", "T._Rowland_Hughes", "words",
   "The quarryman’s son from Llanberis whose five novels, among them O Law i Law and Chwalfa, gave the people of the slate valleys their place in Welsh literature.",
   "Mab y chwarelwr o Lanberis y rhoddodd ei bum nofel, yn eu plith O Law i Law a Chwalfa, eu lle i bobl dyffrynnoedd y llechi yn llenyddiaeth Gymraeg.",
   ["Thomas Rowland Hughes was born in 1903 in Llanberis, under Snowdon, the son of a quarryman. He studied at Bangor and Oxford, taught at Aberdare and at Coleg Harlech, and then joined the BBC in Cardiff, where he wrote and produced radio programmes. He won the chair at the National Eisteddfod in 1937 and again in 1940.",
    "In the 1940s, while he was growing ever weaker from multiple sclerosis, he wrote a novel a year: O Law i Law, William Jones, Yr Ogof, Chwalfa and Y Cychwyn. Chwalfa tells of the great Penrhyn lock-out of 1900 to 1903, and all his books show the warmth, courage and humour of the quarrying families he grew up among. They were some of the most widely read Welsh books of the century. He also wrote the words of the much-loved hymn Tydi a roddaist."],
   ["Ganed Thomas Rowland Hughes yn 1903 yn Llanberis, dan yr Wyddfa, yn fab i chwarelwr. Astudiodd ym Mangor a Rhydychen, bu’n dysgu yn Aberdâr ac yng Ngholeg Harlech, ac yna ymunodd â’r BBC yng Nghaerdydd, lle ysgrifennai a chynhyrchai raglenni radio. Enillodd y gadair yn yr Eisteddfod Genedlaethol yn 1937 ac eto yn 1940.",
    "Yn y 1940au, ac yntau’n gwanhau fwyfwy dan sglerosis ymledol, ysgrifennodd nofel bob blwyddyn: O Law i Law, William Jones, Yr Ogof, Chwalfa ac Y Cychwyn. Mae Chwalfa’n adrodd hanes cloi allan mawr y Penrhyn rhwng 1900 a 1903, ac mae ei holl lyfrau’n dangos cynhesrwydd, dewrder a hiwmor y teuluoedd chwarelyddol y magwyd ef yn eu plith. Roeddent ymhlith llyfrau Cymraeg mwyaf poblogaidd y ganrif. Ef hefyd a ysgrifennodd eiriau’r emyn annwyl Tydi a roddaist."]),
 P("vernon-watkins", "modern", "1906–1967", "Vernon Watkins", "Vernon Watkins", "Poet of Gower", "Bardd Gŵyr", "Vernon_Watkins", "words",
   "The poet from Maesteg who lived his life by the cliffs of Pennard in Gower, Dylan Thomas’s closest friend in poetry.",
   "Y bardd o Faesteg a dreuliodd ei fywyd wrth glogwyni Pennard yng Ngŵyr, cyfaill agosaf Dylan Thomas ym myd barddoniaeth.",
   ["Vernon Watkins was born in 1906 at Maesteg, to Welsh-speaking parents, and grew up in Swansea. He worked for most of his life as a clerk at Lloyds Bank in Swansea, and lived in a house on the cliffs at Pennard in Gower, looking out over the sea that fills his poems. In the Second World War he served at Bletchley Park, working on the codes.",
    "He met Dylan Thomas in the 1930s, and the two became the closest of friends, reading each other their poems as they wrote them. His own books, from Ballad of the Mari Lwyd of 1941 onwards, are full of the old Welsh tales, the seasons of Gower and the hope of the spirit beyond death. He was spoken of for the post of Poet Laureate, and died in 1967 while teaching in Seattle."],
   ["Ganed Vernon Watkins yn 1906 ym Maesteg, i rieni Cymraeg eu hiaith, a magwyd ef yn Abertawe. Gweithiodd y rhan fwyaf o’i oes fel clerc ym Manc Lloyds yn Abertawe, a bu’n byw mewn tŷ ar y clogwyni ym Mhennard yng Ngŵyr, yn edrych dros y môr sy’n llenwi ei gerddi. Yn yr Ail Ryfel Byd gwasanaethodd ym Mletchley Park, yn gweithio ar y codau.",
    "Cyfarfu â Dylan Thomas yn y 1930au, a daeth y ddau’n gyfeillion agos iawn, yn darllen eu cerddi i’w gilydd wrth eu hysgrifennu. Mae ei lyfrau ei hun, o Ballad of the Mari Lwyd yn 1941 ymlaen, yn llawn o’r hen chwedlau Cymreig, tymhorau Gŵyr a gobaith yr ysbryd y tu hwnt i angau. Soniwyd amdano ar gyfer swydd y Bardd Llawryfog, a bu farw yn 1967 tra oedd yn dysgu yn Seattle."]),
 P("glyn-jones", "modern", "1905–1995", "Glyn Jones", "Glyn Jones", "Poet, storyteller and the voice of Merthyr", "Bardd, storïwr a llais Merthyr", "Glyn_Jones_(writer)", "words",
   "The teacher from Merthyr Tydfil whose poems, stories and novels, and his book The Dragon Has Two Tongues, made him the father figure of Welsh writing in English.",
   "Yr athro o Ferthyr Tudful y gwnaeth ei gerddi, ei straeon a’i nofelau, a’i lyfr The Dragon Has Two Tongues, ef yn dad i lenyddiaeth Saesneg Cymru.",
   ["Glyn Jones was born in 1905 in Merthyr Tydfil, to Welsh-speaking parents, and taught for more than forty years in schools in Cardiff. He wrote in English, but he learned Welsh again as a grown man, loved its poetry and translated it, and he brought the rhythms and the music of cynghanedd into his own English verse.",
    "His stories, from The Blue Bed of 1937, and his novels, among them The Valley, the City, the Village and The Island of Apples, are full of the warmth and wonder of the industrial valleys. In 1968 he published The Dragon Has Two Tongues, a book about the Welsh writers in English that is still read today. He was the first chairman of the English-language section of the Welsh Academy, and the Glyn Jones Centre in Cardiff is named after him."],
   ["Ganed Glyn Jones yn 1905 ym Merthyr Tudful, i rieni Cymraeg eu hiaith, a bu’n dysgu am dros ddeugain mlynedd mewn ysgolion yng Nghaerdydd. Ysgrifennai yn Saesneg, ond dysgodd y Gymraeg eto’n ŵr, carodd ei barddoniaeth a’i chyfieithu, a daeth â rhythmau a cherddoriaeth y gynghanedd i’w farddoniaeth Saesneg ei hun.",
    "Mae ei straeon, o The Blue Bed yn 1937, a’i nofelau, yn eu plith The Valley, the City, the Village a The Island of Apples, yn llawn cynhesrwydd a rhyfeddod y cymoedd diwydiannol. Yn 1968 cyhoeddodd The Dragon Has Two Tongues, llyfr am awduron Saesneg Cymru sy’n cael ei ddarllen o hyd. Ef oedd cadeirydd cyntaf adran Saesneg yr Academi Gymreig, ac enwyd Canolfan Glyn Jones yng Nghaerdydd ar ei ôl."]),
 P("gwyn-thomas", "modern", "1913–1981", "Gwyn Thomas", "Gwyn Thomas", "The wit of the Rhondda", "Ffraethineb y Rhondda", "Gwyn_Thomas_(novelist)", "words",
   "The novelist, playwright and broadcaster from Porth whose dazzling, funny books told the story of the Rhondda in the hungry years.",
   "Y nofelydd, y dramodydd a’r darlledwr o’r Porth a adroddodd ei lyfrau disglair a doniol hanes y Rhondda yn y blynyddoedd llwm.",
   ["Gwyn Thomas was born in 1913 at Porth in the Rhondda, the youngest of twelve children of a miner’s family, and won a scholarship to Oxford. He taught languages for many years, at Cardigan and then at Barry, and wrote in the evenings about the valley he came from.",
    "His novels and stories, beginning with The Dark Philosophers in 1946, turned the poverty of the Rhondda in the 1920s and 1930s into comedy of the highest order, full of talk, wit and fierce kindness. His play The Keep of 1961 was a hit in London, and he became one of the best-loved voices on radio and television. His autobiography, A Few Selected Exits, is one of the funniest books ever written about Wales."],
   ["Ganed Gwyn Thomas yn 1913 yn y Porth yn y Rhondda, yr ieuengaf o ddeuddeg o blant teulu glöwr, ac enillodd ysgoloriaeth i Rydychen. Bu’n dysgu ieithoedd am flynyddoedd lawer, yn Aberteifi ac yna yn y Barri, ac ysgrifennai gyda’r nos am y cwm y daeth ohono.",
    "Trodd ei nofelau a’i straeon, gan ddechrau gyda The Dark Philosophers yn 1946, dlodi’r Rhondda yn y 1920au a’r 1930au yn gomedi o’r radd flaenaf, yn llawn siarad, ffraethineb a charedigrwydd ffyrnig. Bu ei ddrama The Keep yn 1961 yn llwyddiant yn Llundain, a daeth yn un o leisiau mwyaf annwyl y radio a’r teledu. Mae ei hunangofiant, A Few Selected Exits, yn un o’r llyfrau mwyaf doniol a ysgrifennwyd erioed am Gymru."]),
 P("rhys-davies", "modern", "1901–1978", "Rhys Davies", "Rhys Davies", "Master of the short story", "Meistr y stori fer", "Rhys_Davies", "words",
   "The grocer’s son from Blaenclydach in the Rhondda who lived by his pen alone and became one of the finest short-story writers in Britain.",
   "Mab y groser o Flaenclydach yn y Rhondda a fu’n byw ar ei ysgrifbin yn unig ac a ddaeth yn un o awduron straeon byrion gorau Prydain.",
   ["Rhys Davies was born in 1901 at Blaenclydach, near Tonypandy, where his parents kept a grocer’s shop. He left for London as a young man and made his living entirely as a writer, which few Welsh authors of his time managed, publishing around a hundred stories, some twenty novels and books about Wales.",
    "Nearly everything he wrote went back to the Rhondda and to rural Wales, to their women and men, their chapels, their passions and their humour. His stories were admired by D. H. Lawrence, who befriended him, and by readers across the world, and his novel The Black Venus and his collection The Trip to London are still read. The Rhys Davies Short Story Award, given every year to Welsh writers, keeps his name alive."],
   ["Ganed Rhys Davies yn 1901 ym Mlaenclydach, ger Tonypandy, lle cadwai ei rieni siop groser. Gadawodd am Lundain yn ŵr ifanc a gwneud ei fywoliaeth yn gyfan gwbl fel awdur, peth na lwyddodd llawer o awduron Cymreig ei gyfnod i’w wneud, gan gyhoeddi tua chant o straeon, rhyw ugain nofel a llyfrau am Gymru.",
    "Âi bron popeth a ysgrifennodd yn ôl i’r Rhondda ac i Gymru wledig, at eu menywod a’u dynion, eu capeli, eu nwydau a’u hiwmor. Edmygwyd ei straeon gan D. H. Lawrence, a ddaeth yn gyfaill iddo, a chan ddarllenwyr ledled y byd, ac mae ei nofel The Black Venus a’i gasgliad The Trip to London yn cael eu darllen o hyd. Mae Gwobr Stori Fer Rhys Davies, a roddir bob blwyddyn i awduron o Gymru, yn cadw ei enw’n fyw."]),
 P("david-jones-artist", "modern", "1895–1974", "David Jones", "David Jones", "Painter and poet of In Parenthesis", "Arlunydd a bardd In Parenthesis", "David_Jones_(artist-poet)", "art",
   "The painter and poet, son of a Welsh printer from Holywell, whose In Parenthesis, about the Royal Welch Fusiliers at Mametz Wood, is one of the great works of the First World War.",
   "Yr arlunydd a’r bardd, mab i argraffydd o Gymro o Dreffynnon, y mae ei In Parenthesis, am y Ffiwsilwyr Cymreig yng Nghoed Mametz, yn un o weithiau mawr y Rhyfel Byd Cyntaf.",
   ["David Jones was born in 1895 in Kent, the son of a printer from Holywell in Flintshire, and from childhood he thought of himself as Welsh. He studied art, and in 1915 joined the Royal Welch Fusiliers, serving on the Western Front until 1918 and being wounded at Mametz Wood in the battle of the Somme, where the Welsh Division fought.",
    "His long work In Parenthesis of 1937, in prose and verse, follows a Welsh battalion from training to Mametz Wood, weaving the soldiers’ talk with Y Gododdin, Malory and the old tales of Britain; it won the Hawthornden Prize, and T. S. Eliot called it a work of genius. The Anathemata of 1952 goes deeper still into the history and myth of the island of Britain. He was also one of the finest British painters and engravers of his century, and his painted inscriptions in Welsh and Latin are much loved."],
   ["Ganed David Jones yn 1895 yng Nghaint, yn fab i argraffydd o Dreffynnon yn Sir y Fflint, ac o’i blentyndod meddyliai amdano’i hun fel Cymro. Astudiodd gelf, ac yn 1915 ymunodd â’r Ffiwsilwyr Cymreig Brenhinol, gan wasanaethu ar y Ffrynt Gorllewinol hyd 1918 a chael ei glwyfo yng Nghoed Mametz ym mrwydr y Somme, lle bu’r Adran Gymreig yn ymladd.",
    "Mae ei waith hir In Parenthesis yn 1937, mewn rhyddiaith a barddoniaeth, yn dilyn bataliwn Cymreig o’r hyfforddi i Goed Mametz, gan blethu siarad y milwyr ag Y Gododdin, Malory a hen chwedlau Prydain; enillodd Wobr Hawthornden, a galwodd T. S. Eliot ef yn waith athrylith. Mae The Anathemata yn 1952 yn mynd yn ddyfnach fyth i hanes a chwedloniaeth ynys Prydain. Roedd hefyd yn un o arlunwyr ac ysgythrwyr gorau Prydain yn ei ganrif, a cherir ei arysgrifau wedi’u peintio yn Gymraeg a Lladin yn fawr."]),

 # ---------- Art, music and stage ----------
 P("ceri-richards", "modern", "1903–1971", "Ceri Richards", "Ceri Richards", "Painter of music and of Dylan’s poems", "Arlunydd cerddoriaeth a cherddi Dylan", "Ceri_Richards", "art",
   "The painter from Dunvant near Swansea whose rich, musical pictures, many inspired by Dylan Thomas, won a prize at the Venice Biennale of 1962.",
   "Yr arlunydd o Dyfnant ger Abertawe y gwnaeth ei luniau cyfoethog, cerddorol, llawer ohonynt wedi eu hysbrydoli gan Dylan Thomas, ennill gwobr yn Biennale Fenis yn 1962.",
   ["Ceri Richards was born in 1903 at Dunvant, near Swansea, in a Welsh-speaking family, the son of a tinplate worker who loved music and poetry. He studied at the Swansea School of Art and then at the Royal College of Art in London, and he became one of the leading British painters of his age.",
    "Music and poetry ran through all his work. He painted many pictures on Dylan Thomas’s poems, among them The force that through the green fuse drives the flower, and after Dylan’s death in 1953 a series in his memory. His series La Cathédrale engloutie, inspired by the piano music of Debussy, is among his best-known works. In 1962 he won the Einaudi painting prize at the Venice Biennale, and he designed stained-glass windows for Derby Cathedral and for the Blessed Sacrament chapel of Liverpool’s Metropolitan Cathedral."],
   ["Ganed Ceri Richards yn 1903 yn Nyfnant, ger Abertawe, i deulu Cymraeg ei iaith, yn fab i weithiwr alcam a garai gerddoriaeth a barddoniaeth. Astudiodd yn Ysgol Gelf Abertawe ac yna yn y Coleg Celf Brenhinol yn Llundain, a daeth yn un o arlunwyr blaenllaw Prydain yn ei oes.",
    "Rhedai cerddoriaeth a barddoniaeth drwy ei holl waith. Peintiodd lawer o luniau ar gerddi Dylan Thomas, yn eu plith The force that through the green fuse drives the flower, ac wedi marw Dylan yn 1953 gyfres er cof amdano. Mae ei gyfres La Cathédrale engloutie, wedi ei hysbrydoli gan gerddoriaeth piano Debussy, ymhlith ei weithiau mwyaf adnabyddus. Yn 1962 enillodd wobr beintio Einaudi yn Biennale Fenis, a chynlluniodd ffenestri lliw i Eglwys Gadeiriol Derby ac i gapel y Sacrament Bendigaid yn Eglwys Gadeiriol Fetropolitan Lerpwl."]),
 P("clara-novello-davies", "industrial", "1861–1943", "Clara Novello Davies", "Clara Novello Davies", "Conductor of the Welsh Ladies’ Choir", "Arweinydd Côr Merched Cymru", "Clara_Novello_Davies", "music",
   "The Cardiff singing teacher whose Welsh Ladies’ Choir won at the Chicago World’s Fair of 1893 and sang before Queen Victoria, and the mother of Ivor Novello.",
   "Yr athrawes ganu o Gaerdydd yr enillodd ei Chôr Merched Cymru yn Ffair y Byd Chicago yn 1893 ac a ganodd o flaen y Frenhines Victoria, a mam Ivor Novello.",
   ["Clara Novello Davies was born in Cardiff in 1861, the daughter of a music-loving family who named her after the great singer Clara Novello. She became a singing teacher and choir conductor in Cardiff, and in the 1880s she formed the Welsh Ladies’ Choir.",
    "In 1893 she took the choir across the Atlantic to the World’s Fair at Chicago, where it won a prize in the great choral contest, and in 1894 it sang for Queen Victoria. She went on to teach singing in London and New York and took her choir on tours round the world. Her son, David Ivor Davies, became famous as Ivor Novello, the composer of Keep the Home Fires Burning and of the great musicals of the London stage."],
   ["Ganed Clara Novello Davies yng Nghaerdydd yn 1861, yn ferch i deulu a garai gerddoriaeth ac a’i henwodd ar ôl y gantores fawr Clara Novello. Daeth yn athrawes ganu ac yn arweinydd côr yng Nghaerdydd, ac yn y 1880au ffurfiodd Gôr Merched Cymru.",
    "Yn 1893 aeth â’r côr dros Fôr Iwerydd i Ffair y Byd yn Chicago, lle enillodd wobr yn y gystadleuaeth gorawl fawr, ac yn 1894 canodd i’r Frenhines Victoria. Aeth ymlaen i ddysgu canu yn Llundain ac Efrog Newydd a mynd â’i chôr ar deithiau o gwmpas y byd. Daeth ei mab, David Ivor Davies, yn enwog fel Ivor Novello, cyfansoddwr Keep the Home Fires Burning a sioeau cerdd mawr llwyfan Llundain."]),
 P("mered", "modern", "1919–2015", "Meredydd Evans", "Merêd", "Singer, scholar of folk song and campaigner", "Canwr, ysgolhaig canu gwerin ac ymgyrchydd", "Meredydd_Evans", "music",
   "The singer from Llanegryn who sang with Triawd y Coleg, saved and studied the folk songs of Wales, and switched off a transmitter to win a Welsh television channel.",
   "Y canwr o Lanegryn a ganodd gyda Thriawd y Coleg, a achubodd ac a astudiodd ganeuon gwerin Cymru, ac a ddiffoddodd drosglwyddydd i ennill sianel deledu Gymraeg.",
   ["Meredydd Evans was born in 1919 at Llanegryn in Meirionnydd and went to study at Bangor. There he formed Triawd y Coleg with Cledwyn Jones and Robin Williams, and their songs on the radio programme Noson Lawen made them loved all over Wales. He went on to Princeton, where he took a doctorate in philosophy, and taught at Boston University.",
    "His 1954 record Welsh Folk-Songs, on the American label Folkways, carried the old songs of Wales to the world, and with his wife Phyllis Kinney he spent a lifetime collecting, editing and singing them. As Head of Light Entertainment at BBC Wales from 1963 to 1973 he brought on young talents such as Ryan Davies and Meic Stevens. In October 1979, aged almost sixty, he joined Ned Thomas and Pennar Davies in switching off the Pencarreg transmitter in protest at the lack of a Welsh-language channel; S4C was born in 1982."],
   ["Ganed Meredydd Evans yn 1919 yn Llanegryn ym Meirionnydd ac aeth i astudio ym Mangor. Yno ffurfiodd Driawd y Coleg gyda Cledwyn Jones a Robin Williams, a gwnaeth eu caneuon ar y rhaglen radio Noson Lawen hwy’n annwyl drwy Gymru gyfan. Aeth ymlaen i Princeton, lle cafodd ddoethuriaeth mewn athroniaeth, a bu’n dysgu ym Mhrifysgol Boston.",
    "Cariodd ei record Welsh Folk-Songs yn 1954, ar y label Americanaidd Folkways, hen ganeuon Cymru i’r byd, a chyda’i wraig Phyllis Kinney treuliodd oes yn eu casglu, eu golygu a’u canu. Fel Pennaeth Adloniant Ysgafn BBC Cymru o 1963 hyd 1973 meithrinodd dalentau ifanc fel Ryan Davies a Meic Stevens. Ym mis Hydref 1979, ac yntau bron yn drigain oed, ymunodd â Ned Thomas a Pennar Davies i ddiffodd trosglwyddydd Pencarreg mewn protest am nad oedd sianel Gymraeg; ganed S4C yn 1982."]),
 P("william-mathias", "modern", "1934–1992", "William Mathias", "William Mathias", "Composer of the royal wedding anthem", "Cyfansoddwr anthem y briodas frenhinol", "William_Mathias", "music",
   "The composer from Whitland whose anthem was sung at the royal wedding of 1981, and who founded the North Wales Music Festival at St Asaph.",
   "Y cyfansoddwr o Hendy-gwyn ar Daf y canwyd ei anthem yn y briodas frenhinol yn 1981, ac a sefydlodd Ŵyl Gerdd Gogledd Cymru yn Llanelwy.",
   ["William Mathias was born in 1934 at Whitland in Carmarthenshire and was playing the piano and composing as a small child. He studied at Aberystwyth and the Royal Academy of Music, and from 1970 to 1988 he was professor of music at Bangor, where he made the department one of the liveliest in Britain.",
    "His music, bright, rhythmic and full of joy, includes symphonies, concertos, an opera on The Servants and a great deal of church music sung all over the world. His anthem Let the people praise thee, O God was sung at the wedding of the Prince and Princess of Wales in 1981 before a television audience of hundreds of millions. In 1972 he founded the North Wales Music Festival in St Asaph Cathedral, which still flourishes."],
   ["Ganed William Mathias yn 1934 yn Hendy-gwyn ar Daf yn Sir Gaerfyrddin ac roedd yn canu’r piano ac yn cyfansoddi’n blentyn bach. Astudiodd yn Aberystwyth ac yn yr Academi Gerdd Frenhinol, ac o 1970 hyd 1988 bu’n athro cerdd ym Mangor, lle gwnaeth yr adran yn un o’r rhai mwyaf bywiog ym Mhrydain.",
    "Mae ei gerddoriaeth, yn llachar, yn rhythmig ac yn llawn llawenydd, yn cynnwys symffonïau, concerti, opera ar The Servants a llawer iawn o gerddoriaeth eglwysig a genir ledled y byd. Canwyd ei anthem Let the people praise thee, O God ym mhriodas Tywysog a Thywysoges Cymru yn 1981 o flaen cynulleidfa deledu o gannoedd o filiynau. Yn 1972 sefydlodd Ŵyl Gerdd Gogledd Cymru yn Eglwys Gadeiriol Llanelwy, sy’n ffynnu o hyd."]),
 P("alun-hoddinott", "modern", "1929–2008", "Alun Hoddinott", "Alun Hoddinott", "Composer and founder of the Cardiff Festival", "Cyfansoddwr a sylfaenydd Gŵyl Caerdydd", "Alun_Hoddinott", "music",
   "The composer from Bargoed who, with William Mathias, gave Wales an orchestral music of its own, and whose name is on BBC Hoddinott Hall in Cardiff Bay.",
   "Y cyfansoddwr o Fargoed a roddodd i Gymru, gyda William Mathias, gerddoriaeth gerddorfaol ei hun, ac y mae ei enw ar Neuadd Hoddinott y BBC ym Mae Caerdydd.",
   ["Alun Hoddinott was born in 1929 at Bargoed in the Rhymney valley and studied music at Cardiff. He taught there for most of his life, and as professor of music from 1967 he built one of the finest music departments in Britain. In the same year he founded the Cardiff Festival of Twentieth Century Music, which brought the leading composers of the world to Wales.",
    "He wrote ten symphonies, many concertos, operas and choral works, often drawing on Welsh poetry and the Welsh landscape, and his music was played by the great orchestras of Britain and America. With William Mathias he showed that Wales could give the world serious music as well as song. When the BBC National Orchestra of Wales moved into its new home at the Wales Millennium Centre in 2009, it was named BBC Hoddinott Hall in his honour."],
   ["Ganed Alun Hoddinott yn 1929 ym Margoed yng Nghwm Rhymni ac astudiodd gerddoriaeth yng Nghaerdydd. Bu’n dysgu yno’r rhan fwyaf o’i oes, ac fel athro cerdd o 1967 adeiladodd un o’r adrannau cerdd gorau ym Mhrydain. Yn yr un flwyddyn sefydlodd Ŵyl Gerdd yr Ugeinfed Ganrif Caerdydd, a ddaeth â chyfansoddwyr blaenllaw’r byd i Gymru.",
    "Ysgrifennodd ddeg symffoni, llawer o goncerti, operâu a gweithiau corawl, gan dynnu’n aml ar farddoniaeth a thirwedd Cymru, a chwaraewyd ei gerddoriaeth gan gerddorfeydd mawr Prydain ac America. Gyda William Mathias dangosodd y gallai Cymru roi i’r byd gerddoriaeth ddifrifol yn ogystal â chân. Pan symudodd Cerddorfa Genedlaethol Gymreig y BBC i’w chartref newydd yng Nghanolfan Mileniwm Cymru yn 2009, fe’i henwyd yn Neuadd Hoddinott y BBC er anrhydedd iddo."]),
 P("margaret-price", "modern", "1941–2011", "Dame Margaret Price", "Y Fonesig Margaret Price", "The great Mozart soprano", "Y soprano Mozart fawr", "Margaret_Price", "music",
   "The soprano from Blackwood who became one of the finest Mozart and Verdi singers in the world, the star of the Munich opera for twenty years.",
   "Y soprano o’r Coed-duon a ddaeth yn un o gantorion Mozart a Verdi gorau’r byd, seren opera München am ugain mlynedd.",
   ["Margaret Price was born in 1941 at Blackwood in Gwent. A singing teacher heard her voice, and she won a scholarship to Trinity College of Music in London. In 1963, aged twenty-one, she stepped in at short notice as Cherubino in Mozart’s Marriage of Figaro at Covent Garden and was a sensation.",
    "She went on to sing the great roles of Mozart, Verdi and Strauss in the opera houses of the world, from Vienna and Paris to the Metropolitan in New York, and for twenty years she was a star of the Bavarian State Opera in Munich. Her voice was known for its purity and beauty, and her recordings of Mozart and of song are treasured. She was made a Dame in 1993, and came home to live in Ceibwr, on the coast of Pembrokeshire, where she died in 2011."],
   ["Ganed Margaret Price yn 1941 yn y Coed-duon yng Ngwent. Clywodd athrawes ganu ei llais, ac enillodd ysgoloriaeth i Goleg Cerdd y Drindod yn Llundain. Yn 1963, yn un ar hugain oed, camodd i’r adwy ar fyr rybudd fel Cherubino ym Mhriodas Figaro Mozart yn Covent Garden a chreu cynnwrf.",
    "Aeth ymlaen i ganu rhannau mawr Mozart, Verdi a Strauss yn nhai opera’r byd, o Fienna a Pharis i’r Metropolitan yn Efrog Newydd, ac am ugain mlynedd bu’n seren Opera Talaith Bafaria ym München. Roedd ei llais yn enwog am ei burdeb a’i harddwch, a thrysorir ei recordiau o Mozart ac o ganeuon. Fe’i gwnaed yn Fonesig yn 1993, a daeth adref i fyw yng Ngheibwr, ar arfordir Sir Benfro, lle bu farw yn 2011."]),
 P("emlyn-williams", "modern", "1905–1987", "Emlyn Williams", "Emlyn Williams", "Playwright of The Corn Is Green", "Dramodydd The Corn Is Green", "Emlyn_Williams", "stage",
   "The Welsh-speaking boy from Flintshire who won a scholarship to Oxford, wrote Night Must Fall and The Corn Is Green, and became a star of stage and screen.",
   "Y bachgen Cymraeg o Sir y Fflint a enillodd ysgoloriaeth i Rydychen, a ysgrifennodd Night Must Fall a The Corn Is Green, ac a ddaeth yn seren llwyfan a sgrin.",
   ["George Emlyn Williams was born in 1905 at Pen-y-ffordd near Mostyn in Flintshire, the son of a labourer, and spoke only Welsh until he was eight. A gifted teacher at Holywell county school, Sarah Grace Cooke, saw his brilliance and taught him, and he won a scholarship to Christ Church, Oxford.",
    "He became both actor and playwright, and his thriller Night Must Fall of 1935 made his name in London and New York. In The Corn Is Green of 1938 he told his own story, of a young Welsh miner and the teacher who opens the world to him, and it was played around the world and filmed with Bette Davis. In later years his one-man shows as Charles Dickens and as Dylan Thomas toured the world. His autobiography George is one of the great books about a Welsh childhood."],
   ["Ganed George Emlyn Williams yn 1905 ym Mhen-y-ffordd ger Mostyn yn Sir y Fflint, yn fab i labrwr, a dim ond Cymraeg a siaradai nes ei fod yn wyth oed. Gwelodd athrawes ddawnus yn ysgol sir Treffynnon, Sarah Grace Cooke, ei ddisgleirdeb a’i ddysgu, ac enillodd ysgoloriaeth i Christ Church, Rhydychen.",
    "Daeth yn actor ac yn ddramodydd, a gwnaeth ei ddrama ias Night Must Fall yn 1935 ei enw yn Llundain ac Efrog Newydd. Yn The Corn Is Green yn 1938 adroddodd ei hanes ei hun, am löwr ifanc o Gymro a’r athrawes sy’n agor y byd iddo, ac fe’i chwaraewyd ledled y byd a’i ffilmio gyda Bette Davis. Yn ddiweddarach teithiodd ei sioeau un dyn fel Charles Dickens ac fel Dylan Thomas y byd. Mae ei hunangofiant George yn un o’r llyfrau mawr am blentyndod yng Nghymru."]),
 P("stanley-baker", "modern", "1928–1976", "Sir Stanley Baker", "Syr Stanley Baker", "Star and maker of Zulu", "Seren a gwneuthurwr Zulu", "Stanley_Baker", "stage",
   "The miner’s son from Ferndale who became a film star, produced and starred in Zulu, and put the Welsh soldiers and their singing on the big screen.",
   "Mab y glöwr o Lynrhedynog a ddaeth yn seren ffilm, a gynhyrchodd ac a serennodd yn Zulu, ac a roddodd y milwyr Cymreig a’u canu ar y sgrin fawr.",
   ["Stanley Baker was born in 1928 at Ferndale in the Rhondda, the son of a miner. A teacher spotted his talent for acting, and he was in films by the age of fourteen. He became one of the leading British film actors of the 1950s and 1960s, known for tough, strong parts, in films such as The Cruel Sea, Hell Drivers and The Guns of Navarone.",
    "In 1964 he co-produced and starred in Zulu, the story of the defence of Rorke’s Drift in 1879 by a company of the 24th Regiment, with Welsh soldiers singing Men of Harlech, and it became one of the best-loved British films ever made. He also worked to bring film-making and broadcasting to Wales. He was knighted in 1976, shortly before he died at the age of forty-eight."],
   ["Ganed Stanley Baker yn 1928 yng Nglynrhedynog yn y Rhondda, yn fab i löwr. Sylwodd athro ar ei ddawn actio, ac roedd mewn ffilmiau erbyn ei fod yn bedair ar ddeg oed. Daeth yn un o actorion ffilm blaenllaw Prydain yn y 1950au a’r 1960au, yn enwog am rannau caled, cryf, mewn ffilmiau fel The Cruel Sea, Hell Drivers a The Guns of Navarone.",
    "Yn 1964 cyd-gynhyrchodd a serennodd yn Zulu, hanes amddiffyn Rorke’s Drift yn 1879 gan gwmni o’r 24ain Gatrawd, gyda milwyr Cymreig yn canu Rhyfelgyrch Gwŷr Harlech, a daeth yn un o’r ffilmiau Prydeinig mwyaf annwyl a wnaed erioed. Gweithiodd hefyd i ddod â gwneud ffilmiau a darlledu i Gymru. Fe’i hurddwyd yn farchog yn 1976, yn fuan cyn iddo farw yn wyth a deugain oed."]),
 P("desmond-llewelyn", "modern", "1914–1999", "Desmond Llewelyn", "Desmond Llewelyn", "Q in the James Bond films", "Q yn ffilmiau James Bond", "Desmond_Llewelyn", "stage",
   "The actor from Newport who survived five years as a prisoner of war, including Colditz, and played Q, the gadget master, in seventeen James Bond films.",
   "Yr actor o Gasnewydd a oroesodd bum mlynedd yn garcharor rhyfel, gan gynnwys Colditz, ac a chwaraeodd Q, meistr y teclynnau, mewn dwy ar bymtheg o ffilmiau James Bond.",
   ["Desmond Llewelyn was born in 1914 at Bettws, Newport, the son of a mining engineer. He trained as an actor in London, and when war came he was commissioned in the Royal Welch Fusiliers. In 1940, during the retreat to Dunkirk, his unit was overrun near Lille and he was taken prisoner. He spent five years in German prison camps, and after a tunnelling escape attempt he was sent to Colditz Castle, where he stayed until it was liberated in 1945.",
    "After the war he went back to the stage, television and films. In 1963 he first played Q, the head of the secret service’s workshop, in From Russia with Love, and he played him in seventeen Bond films over thirty-six years, the last being The World Is Not Enough in 1999, more than any other actor in the series. His grumbling ‘Now pay attention, 007’ made him loved by audiences all over the world."],
   ["Ganed Desmond Llewelyn yn 1914 ym Metws, Casnewydd, yn fab i beiriannydd mwyngloddio. Hyfforddodd fel actor yn Llundain, a phan ddaeth y rhyfel cafodd gomisiwn yn y Ffiwsilwyr Cymreig Brenhinol. Yn 1940, yn ystod yr enciliad i Dunkirk, gorchfygwyd ei uned ger Lille a chymerwyd ef yn garcharor. Treuliodd bum mlynedd yng ngwersylloedd carchar yr Almaen, ac wedi ymgais i ddianc drwy dwnnel fe’i hanfonwyd i Gastell Colditz, lle bu nes ei ryddhau yn 1945.",
    "Wedi’r rhyfel aeth yn ôl i’r llwyfan, y teledu a’r ffilmiau. Yn 1963 chwaraeodd Q, pennaeth gweithdy’r gwasanaeth cudd, am y tro cyntaf yn From Russia with Love, a chwaraeodd ef mewn dwy ar bymtheg o ffilmiau Bond dros dri deg chwech o flynyddoedd, a’r olaf oedd The World Is Not Enough yn 1999, mwy nag unrhyw actor arall yn y gyfres. Gwnaeth ei rwgnach ‘Now pay attention, 007’ ef yn annwyl i gynulleidfaoedd ledled y byd."]),

 # ---------- Campaigners and learning ----------
 P("rachel-barrett", "modern", "1874–1953", "Rachel Barrett", "Rachel Barrett", "Suffragette leader in Wales", "Arweinydd y swffragetiaid yng Nghymru", "Rachel_Barrett", "heroes",
   "The science teacher from Carmarthen who led the women’s suffrage campaign in Wales, edited The Suffragette and went on hunger strike for the vote.",
   "Yr athrawes wyddoniaeth o Gaerfyrddin a arweiniodd ymgyrch y bleidlais i fenywod yng Nghymru, a olygodd The Suffragette ac a aeth ar streic newyn dros y bleidlais.",
   ["Rachel Barrett was born in Carmarthen in 1874 and won a scholarship to the University College of Wales, Aberystwyth, where she graduated in science in 1904 and became a science teacher. In 1906 she heard the suffragette Nellie Martel speak and joined the Women’s Social and Political Union, and two years later she gave up teaching to work for the cause full time.",
    "From Cardiff she organised the campaign for votes for women across the whole of Wales, travelling from town to town to speak in the open air. In 1912 she became assistant editor of the movement’s newspaper, The Suffragette, and kept it printing when the government tried to stop it. In 1913 she was sentenced to nine months in Holloway; she went on hunger strike again and again and was released under the Cat and Mouse Act, then edited the paper in hiding. She lived to see women win the vote on equal terms with men in 1928."],
   ["Ganed Rachel Barrett yng Nghaerfyrddin yn 1874 ac enillodd ysgoloriaeth i Goleg Prifysgol Cymru, Aberystwyth, lle graddiodd mewn gwyddoniaeth yn 1904 a dod yn athrawes wyddoniaeth. Yn 1906 clywodd y swffragét Nellie Martel yn siarad ac ymunodd â’r Women’s Social and Political Union, a dwy flynedd yn ddiweddarach rhoddodd y gorau i ddysgu i weithio dros yr achos yn llawn amser.",
    "O Gaerdydd trefnodd yr ymgyrch dros bleidlais i fenywod drwy Gymru gyfan, gan deithio o dref i dref i siarad yn yr awyr agored. Yn 1912 daeth yn ddirprwy olygydd papur newydd y mudiad, The Suffragette, a’i gadw i argraffu pan geisiodd y llywodraeth ei atal. Yn 1913 fe’i dedfrydwyd i naw mis yn Holloway; aeth ar streic newyn dro ar ôl tro a’i rhyddhau dan Ddeddf y Gath a’r Llygoden, ac yna golygodd y papur o’i chuddfan. Bu fyw i weld menywod yn ennill y bleidlais ar yr un telerau â dynion yn 1928."]),
 P("gwyn-alf-williams", "modern", "1925–1995", "Gwyn Alf Williams", "Gwyn Alf Williams", "The people’s historian of Wales", "Hanesydd y bobl yng Nghymru", "Gwyn_Alf_Williams", "learning",
   "The historian from Dowlais who wrote When Was Wales? and The Merthyr Rising, and brought the story of the Welsh people to millions on television.",
   "Yr hanesydd o Ddowlais a ysgrifennodd When Was Wales? a The Merthyr Rising, ac a ddaeth â hanes pobl Cymru i filiynau ar y teledu.",
   ["Gwyn Alfred Williams was born in 1925 at Dowlais, Merthyr Tydfil, to a Welsh-speaking family of teachers, and served in the army in the Second World War before studying at Aberystwyth. He became a professor of history at York and then, from 1974, at Cardiff, and he wrote with fire and learning about Spain, France, Italy and, above all, Wales.",
    "His The Merthyr Rising of 1978 told the story of 1831 and Dic Penderyn from the side of the working people, and When Was Wales? of 1985 asked how a small nation had made and remade itself through two thousand years. With Wynford Vaughan-Thomas he presented The Dragon Has Two Tongues, a television history of Wales in thirteen parts, and his stammer, his passion and his wit made him one of the great broadcasters of his day. He spent his last years in Dyfed, and is remembered as the people’s historian."],
   ["Ganed Gwyn Alfred Williams yn 1925 yn Nowlais, Merthyr Tudful, i deulu o athrawon Cymraeg eu hiaith, a gwasanaethodd yn y fyddin yn yr Ail Ryfel Byd cyn astudio yn Aberystwyth. Daeth yn athro hanes yn Efrog ac yna, o 1974, yng Nghaerdydd, ac ysgrifennodd gyda thân a dysg am Sbaen, Ffrainc, yr Eidal ac, yn anad dim, Gymru.",
    "Adroddodd ei The Merthyr Rising yn 1978 hanes 1831 a Dic Penderyn o ochr y gweithwyr, a gofynnodd When Was Wales? yn 1985 sut yr oedd cenedl fechan wedi ei gwneud a’i hailwneud ei hun drwy ddwy fil o flynyddoedd. Gyda Wynford Vaughan-Thomas cyflwynodd The Dragon Has Two Tongues, hanes teledu o Gymru mewn tair rhan ar ddeg, a gwnaeth ei atal dweud, ei angerdd a’i ffraethineb ef yn un o ddarlledwyr mawr ei ddydd. Treuliodd ei flynyddoedd olaf yn Nyfed, ac fe’i cofir fel hanesydd y bobl."]),

 # ---------- Sport ----------
 P("cliff-morgan", "modern", "1930–2013", "Cliff Morgan", "Cliff Morgan", "The magic fly-half and voice of rugby", "Y maswr hudol a llais y rygbi", "Cliff_Morgan", "sport",
   "The fly-half from Trebanog who dazzled for Wales and the Lions in South Africa in 1955, and whose voice described the most famous try in rugby.",
   "Y maswr o Drebanog a ddisgleiriodd i Gymru a’r Llewod yn Ne Affrica yn 1955, ac y disgrifiodd ei lais y cais enwocaf mewn rygbi.",
   ["Cliff Morgan was born in 1930 at Trebanog in the Rhondda, in a Welsh-speaking family, and played fly-half for Cardiff and for Wales, winning twenty-nine caps between 1951 and 1958. Small, quick and full of daring, he was the heart of the Welsh side that beat the All Blacks in 1953 and won the Grand Slam in 1952.",
    "On the British Lions tour of South Africa in 1955 he was the star of the series, and captained the side in the third Test; the South Africans called him the greatest fly-half they had seen. After rugby he became a broadcaster and rose to be head of outside broadcasts at the BBC. At Cardiff Arms Park in 1973 it was his voice that described Gareth Edwards’s try for the Barbarians against New Zealand, ‘What a score!’, the most famous commentary in the game."],
   ["Ganed Cliff Morgan yn 1930 yn Nhrebanog yn y Rhondda, i deulu Cymraeg ei iaith, a chwaraeodd fel maswr i Gaerdydd ac i Gymru, gan ennill naw cap ar hugain rhwng 1951 a 1958. Yn fach, yn gyflym ac yn llawn mentr, ef oedd calon y tîm Cymreig a gurodd y Crysau Duon yn 1953 ac a enillodd y Gamp Lawn yn 1952.",
    "Ar daith y Llewod Prydeinig i Dde Affrica yn 1955 ef oedd seren y gyfres, a bu’n gapten y tîm yn y trydydd prawf; galwai’r De Affricaniaid ef y maswr gorau a welsant erioed. Wedi’r rygbi daeth yn ddarlledwr a chodi’n bennaeth darllediadau allanol y BBC. Ym Mharc yr Arfau yn 1973 ei lais ef a ddisgrifiodd gais Gareth Edwards i’r Barbariaid yn erbyn Seland Newydd, ‘What a score!’, y sylwebaeth enwocaf yn y gêm."]),
 P("ray-gravell", "modern", "1951–2007", "Ray Gravell", "Ray Gravell", "Grand Slam centre and voice of Radio Cymru", "Canolwr y Gamp Lawn a llais Radio Cymru", "Ray_Gravell", "sport",
   "The centre from Mynydd-y-Garreg who won two Grand Slams with Wales, toured with the Lions, and became one of the best-loved voices of Welsh-language broadcasting.",
   "Y canolwr o Fynydd-y-Garreg a enillodd ddwy Gamp Lawn gyda Chymru, a aeth ar daith gyda’r Llewod, ac a ddaeth yn un o leisiau mwyaf annwyl darlledu Cymraeg.",
   ["Ray Gravell was born in 1951 and grew up at Mynydd-y-Garreg, near Kidwelly, a proud Welsh speaker all his life. He played in the centre for Llanelli, and was in the Scarlets side that beat the All Blacks at Stradey Park in 1972. He won twenty-three caps for Wales, and was part of the Grand Slam teams of 1976 and 1978, and in 1980 he toured South Africa with the British Lions, playing in all four Tests.",
    "After rugby he became one of the most loved figures in Wales, a broadcaster on Radio Cymru and S4C and an actor in films and television. He was proud to serve as the Grand Sword Bearer of the Gorsedd at the National Eisteddfod. His warmth, his tears at the anthem and his love of Wales and its language made him a national treasure, and the people of Wales mourned him deeply when he died in 2007."],
   ["Ganed Ray Gravell yn 1951 a magwyd ef ym Mynydd-y-Garreg, ger Cydweli, yn Gymro Cymraeg balch ar hyd ei oes. Chwaraeai yn y canol i Lanelli, ac roedd yn nhîm y Sgarlets a gurodd y Crysau Duon ar Barc y Strade yn 1972. Enillodd dri chap ar hugain i Gymru, ac roedd yn rhan o dimau’r Gamp Lawn yn 1976 a 1978, ac yn 1980 aeth ar daith i Dde Affrica gyda’r Llewod Prydeinig, gan chwarae ym mhob un o’r pedwar prawf.",
    "Wedi’r rygbi daeth yn un o ffigurau mwyaf annwyl Cymru, yn ddarlledwr ar Radio Cymru ac S4C ac yn actor mewn ffilmiau a theledu. Roedd yn falch o wasanaethu fel Ceidwad y Cledd yng Ngorsedd yr Eisteddfod Genedlaethol. Gwnaeth ei gynhesrwydd, ei ddagrau adeg yr anthem a’i gariad at Gymru a’i hiaith ef yn drysor cenedlaethol, a galarodd pobl Cymru’n ddwys amdano pan fu farw yn 2007."]),
 P("ivor-allchurch", "modern", "1929–1997", "Ivor Allchurch", "Ivor Allchurch", "The Golden Boy of Welsh football", "Bachgen Aur pêl-droed Cymru", "Ivor_Allchurch", "sport",
   "The inside forward from Swansea, the Golden Boy, who played sixty-eight times for Wales and helped take them to the quarter-finals of the 1958 World Cup.",
   "Y blaenwr mewnol o Abertawe, y Bachgen Aur, a chwaraeodd wyth gwaith a thrigain i Gymru ac a helpodd i’w harwain i rownd yr wyth olaf yng Nghwpan y Byd 1958.",
   ["Ivor Allchurch was born in Swansea in 1929 and joined Swansea Town as a boy. Graceful, balanced and a beautiful passer and finisher of the ball, he became known as the Golden Boy, and he went on to play for Newcastle United and Cardiff City before going home to Swansea, scoring some 250 league goals in a long career.",
    "He won sixty-eight caps for Wales between 1950 and 1966, a record for many years, and scored twenty-three goals. In 1958 he was one of the stars of the Welsh team, with John Charles, that reached the quarter-finals of the World Cup in Sweden, where he scored a famous volley against Hungary. He was made an MBE in 1966."],
   ["Ganed Ivor Allchurch yn Abertawe yn 1929 ac ymunodd ag Abertawe’n fachgen. Yn osgeiddig, yn gytbwys ac yn pasio a gorffen yn hardd, daeth yn enwog fel y Bachgen Aur, ac aeth ymlaen i chwarae i Newcastle United a Chaerdydd cyn mynd adref i Abertawe, gan sgorio tua 250 o goliau cynghrair mewn gyrfa hir.",
    "Enillodd wyth cap a thrigain i Gymru rhwng 1950 a 1966, record am flynyddoedd lawer, a sgoriodd dair gôl ar hugain. Yn 1958 roedd yn un o sêr y tîm Cymreig, gyda John Charles, a gyrhaeddodd rownd yr wyth olaf yng Nghwpan y Byd yn Sweden, lle sgoriodd foli enwog yn erbyn Hwngari. Fe’i gwnaed yn MBE yn 1966."]),
 P("howard-winstone", "modern", "1939–2000", "Howard Winstone", "Howard Winstone", "World featherweight champion", "Pencampwr pwysau plu’r byd", "Howard_Winstone", "sport",
   "The boxer from Merthyr Tydfil who lost the tips of three fingers in a factory accident and still became champion of the world.",
   "Y bocsiwr o Ferthyr Tudful a gollodd flaenau tri bys mewn damwain mewn ffatri ac a ddaeth, er hynny, yn bencampwr y byd.",
   ["Howard Winstone was born in Merthyr Tydfil in 1939. As a teenager working in a toy factory he lost the tips of three fingers of his right hand in a machine, a blow that would have ended most boxers’ hopes. Instead he learned to box with a lightning left hand and perfect footwork, and in 1958 he won the bantamweight gold medal at the Empire and Commonwealth Games in Cardiff, in front of a Welsh crowd.",
    "As a professional he became British and European featherweight champion, and fought three great battles for the world title against the Mexican Vicente Saldívar. In January 1968, at the Royal Albert Hall, he beat Mitsunori Seki of Japan to become champion of the world. He died in Merthyr in 2000, and a bronze statue of him stands in St Tydfil’s Square, and a film, Risen, tells his story."],
   ["Ganed Howard Winstone ym Merthyr Tudful yn 1939. Yn ei arddegau, ac yntau’n gweithio mewn ffatri deganau, collodd flaenau tri bys ei law dde mewn peiriant, ergyd a fyddai wedi rhoi diwedd ar obeithion y rhan fwyaf o focswyr. Yn hytrach dysgodd focsio â llaw chwith fel mellten a symud ei draed yn berffaith, ac yn 1958 enillodd y fedal aur pwysau bantam yng Ngemau’r Ymerodraeth a’r Gymanwlad yng Nghaerdydd, o flaen torf Gymreig.",
    "Fel bocsiwr proffesiynol daeth yn bencampwr pwysau plu Prydain ac Ewrop, ac ymladdodd dair brwydr fawr am deitl y byd yn erbyn Vicente Saldívar o Fecsico. Ym mis Ionawr 1968, yn y Royal Albert Hall, curodd Mitsunori Seki o Japan i ddod yn bencampwr y byd. Bu farw ym Merthyr yn 2000, ac mae cerflun efydd ohono’n sefyll yn Sgwâr Tudful Sant, ac mae ffilm, Risen, yn adrodd ei hanes."]),
 P("dai-rees", "modern", "1913–1983", "Dai Rees", "Dai Rees", "The captain who won the Ryder Cup", "Y capten a enillodd Gwpan Ryder", "Dai_Rees", "sport",
   "The golfer from the Vale of Glamorgan who captained Great Britain to victory in the Ryder Cup of 1957, their first win over the Americans for twenty-four years.",
   "Y golffiwr o Fro Morgannwg a arweiniodd Brydain Fawr i fuddugoliaeth yng Nghwpan Ryder 1957, eu buddugoliaeth gyntaf dros yr Americanwyr ers pedair blynedd ar hugain.",
   ["David James Rees was born in 1913 at Fontygary in the Vale of Glamorgan, the son of a golf professional, and learned the game as a boy. He became one of the finest British golfers of his time, a fighter on the course who won tournaments for more than thirty years and twice took the Harry Vardon Trophy for the best scoring of the season.",
    "He played in nine Ryder Cups for Great Britain and was captain five times. At Lindrick in Yorkshire in 1957 he led his team against the United States, who had not lost the cup since 1933, and won his own singles match as Great Britain triumphed by seven and a half points to four and a half. That year he was voted BBC Sports Personality of the Year, and he was made a CBE in 1958."],
   ["Ganed David James Rees yn 1913 yn Ffontygari ym Mro Morgannwg, yn fab i golffiwr proffesiynol, a dysgodd y gêm yn fachgen. Daeth yn un o golffwyr gorau Prydain yn ei gyfnod, yn ymladdwr ar y cwrs a enillodd bencampwriaethau am dros ddeng mlynedd ar hugain ac a gipiodd Dlws Harry Vardon ddwywaith am sgorio gorau’r tymor.",
    "Chwaraeodd mewn naw o gystadlaethau Cwpan Ryder i Brydain Fawr a bu’n gapten bum gwaith. Yn Lindrick yn Swydd Efrog yn 1957 arweiniodd ei dîm yn erbyn yr Unol Daleithiau, nad oeddent wedi colli’r cwpan ers 1933, ac enillodd ei gêm sengl ei hun wrth i Brydain Fawr fuddugoliaethu o saith pwynt a hanner i bedwar a hanner. Y flwyddyn honno fe’i dewiswyd yn Bersonoliaeth Chwaraeon y Flwyddyn y BBC, ac fe’i gwnaed yn CBE yn 1958."]),
]
